function box(x1,y1,z1,x2,y2,z2,t){
  var a=Math.min(x1,x2),b=Math.max(x1,x2);
  var c=Math.min(y1,y2),d=Math.max(y1,y2);
  var e=Math.min(z1,z2),f=Math.max(z1,z2);
  for(var x=a;x<=b;x++)for(var y=c;y<=d;y++)for(var z=e;z<=f;z++)if(x>=0&&x<256&&y>=0&&y<256&&z>=0&&z<256)block(x,y,z,t);
}
function cyl_h(cx,cy,cz,r,h,t){
  for(var y=cy;y<cy+h;y++)for(var x=cx-r;x<=cx+r;x++)for(var z=cz-r;z<=cz+r;z++)
    if((x-cx)*(x-cx)+(z-cz)*(z-cz)<=r*r&&x>=0&&x<256&&y>=0&&y<256&&z>=0&&z<256)block(x,y,z,t);
}
function cyl_v(cx,cy,cz,r,h,t){
  for(var y=cy;y<cy+h;y++)for(var x=cx-r;x<=cx+r;x++)for(var z=cz-r;z<=cz+r;z++)
    if((x-cx)*(x-cx)+(z-cz)*(z-cz)<=r*r&&x>=0&&x<256&&y>=0&&y<256&&z>=0&&z<256)block(x,y,z,t);
}
function sphere(cx,cy,cz,r,t){
  var r2=r*r;
  for(var x=cx-r;x<=cx+r;x++)for(var y=cy-r;y<=cy+r;y++)for(var z=cz-r;z<=cz+r;z++)
    if((x-cx)*(x-cx)+(y-cy)*(y-cy)+(z-cz)*(z-cz)<=r2&&x>=0&&x<256&&y>=0&&y<256&&z>=0&&z<256)block(x,y,z,t);
}
